(function () {
  const videos = [
    "data:video/mp4;base64,",
    "data:video/mp4;base64,"
  ];
  let previous = -1;
  try {
    previous = Number(localStorage.getItem("emibHeroLastVideo"));
  } catch (error) {}
  let available = videos.map((_, index) => index).filter(index => index !== previous);
  if (!available.length) available = videos.map((_, index) => index);
  const selected = available[Math.floor(Math.random() * available.length)];
  try {
    localStorage.setItem("emibHeroLastVideo", String(selected));
  } catch (error) {}
  const video = document.getElementById("emib-hero-video");
  video.src = videos[selected];
  video.load();
  const startPlayback = () => video.play().catch(() => {});
  startPlayback();
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && video.paused) startPlayback();
  });
})();

const toggle=document.querySelector('.menu-toggle');
const menu=document.querySelector('.nav-links');
toggle?.addEventListener('click',()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',open);});
document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>menu.classList.remove('open')));
document.querySelectorAll('.video-shell').forEach(shell=>{
  const button=shell.querySelector('.video-poster');
  button?.addEventListener('click',()=>{
    const id=shell.dataset.video;
    const iframe=document.createElement('iframe');
    iframe.src='https://www.youtube.com/embed/'+id+'?autoplay=1';
    iframe.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
    iframe.allowFullscreen=true;
    button.replaceWith(iframe);
  });
});